package com.learningspace;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import org.json.*;
public class StudyTimerService extends Service {
 public static final int NOTIFICATION_ID=4101;public static final String CHANNEL="focus_session";
 private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable limit=new Runnable(){public void run(){StudyTimerState s=StudyTimerStore.read(StudyTimerService.this);if(s==null){stopSelf();return;}if(!s.running||s.elapsed(SystemClock.elapsedRealtime())>=StudyTimerState.MAX_MS)pause(StudyTimerService.this,s.id);else handler.postDelayed(this,Math.min(60000,Math.max(1,StudyTimerState.MAX_MS-s.elapsed(SystemClock.elapsedRealtime()))));}};
 private boolean clockReceiverRegistered=false;
 private final BroadcastReceiver clockChanged=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent intent){StudyTimerState s=StudyTimerStore.read(c);if(s!=null&&s.running)try{getSystemService(NotificationManager.class).notify(NOTIFICATION_ID,build(c,s));}catch(Exception ignored){}}};
 @Override public void onCreate(){super.onCreate();try{IntentFilter filter=new IntentFilter(Intent.ACTION_TIME_CHANGED);if(Build.VERSION.SDK_INT>=33)registerReceiver(clockChanged,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(clockChanged,filter);clockReceiverRegistered=true;}catch(Exception ignored){}}

 public static void channel(Context c){NotificationChannel channel=new NotificationChannel(CHANNEL,"Focus session timer",NotificationManager.IMPORTANCE_LOW);channel.setDescription("Live study stopwatch with pause, resume, and finish controls");channel.setSound(null,null);c.getSystemService(NotificationManager.class).createNotificationChannel(channel);}
 public static boolean notificationsEnabled(Context c){NotificationManager m=c.getSystemService(NotificationManager.class);NotificationChannel ch=m.getNotificationChannel(CHANNEL);return m.areNotificationsEnabled()&&(ch==null||ch.getImportance()!=NotificationManager.IMPORTANCE_NONE);}
 private static PendingIntent open(Context c,String id,boolean finish){Intent i=new Intent(c,MainActivity.class).putExtra("timer_session",id).putExtra("timer_finish",finish).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);return PendingIntent.getActivity(c,finish?4103:4102,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static PendingIntent action(Context c,String id,String action){Intent i=new Intent(c,StudyTimerService.class).setAction(action).putExtra("timer_session",id);return PendingIntent.getForegroundService(c,action.equals("resume")?4105:4104,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static String time(long ms){long seconds=ms/1000;return String.format(java.util.Locale.US,"%d:%02d",seconds/60,seconds%60);}
 private static Notification build(Context c,StudyTimerState s){long elapsed=s.elapsed(SystemClock.elapsedRealtime());Notification.Builder b=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_timer_notification).setContentTitle(s.lessonTitle).setContentText(s.running?s.resourceTitle:"Paused · "+time(elapsed)+" · "+s.resourceTitle).setSubText(s.plannedMinutes+" min focus block").setContentIntent(open(c,s.id,false)).setCategory(Notification.CATEGORY_PROGRESS).setOngoing(s.running).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PRIVATE).setShowWhen(s.running).setWhen(System.currentTimeMillis()-elapsed).setUsesChronometer(s.running).setChronometerCountDown(false).addAction(new Notification.Action.Builder(s.running?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,s.running?"Pause":"Resume",action(c,s.id,s.running?"pause":"resume")).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_save,"Finish",open(c,s.id,true)).build());if(Build.VERSION.SDK_INT>=31)b.setForegroundServiceBehavior(Notification.FOREGROUND_SERVICE_IMMEDIATE);Notification pub=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_timer_notification).setContentTitle("Learning Space").setContentText(s.running?"Focus session in progress":"Focus session paused").setShowWhen(s.running).setWhen(System.currentTimeMillis()-elapsed).setUsesChronometer(s.running).build();return b.setPublicVersion(pub).build();}
 public static void pause(Context c,String id){try{StudyTimerState s=StudyTimerStore.change(c,id,"pause");c.stopService(new Intent(c,StudyTimerService.class));channel(c);if(s!=null&&notificationsEnabled(c))c.getSystemService(NotificationManager.class).notify(NOTIFICATION_ID,build(c,s));}catch(Exception ignored){}}
 public static void clear(Context c,String id)throws Exception{StudyTimerStore.change(c,id,"clear");c.stopService(new Intent(c,StudyTimerService.class));c.getSystemService(NotificationManager.class).cancel(NOTIFICATION_ID);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){channel(this);StudyTimerState s=StudyTimerStore.read(this);if(s==null){stopSelf();return START_NOT_STICKY;}String id=intent==null?s.id:intent.getStringExtra("timer_session");String action=intent==null||!s.id.equals(id)?"restore":intent.getAction();try{if("resume".equals(action))s=StudyTimerStore.change(this,s.id,"resume");else if("pause".equals(action))s=StudyTimerStore.change(this,s.id,"pause");Notification n=build(this,s);if(Build.VERSION.SDK_INT>=34)startForeground(NOTIFICATION_ID,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(NOTIFICATION_ID,n);handler.removeCallbacks(limit);if(!s.running){stopForeground(STOP_FOREGROUND_DETACH);getSystemService(NotificationManager.class).notify(NOTIFICATION_ID,n);stopSelf();return START_NOT_STICKY;}handler.postDelayed(limit,Math.min(60000,Math.max(1,StudyTimerState.MAX_MS-s.elapsed(SystemClock.elapsedRealtime()))));return START_STICKY;}catch(Exception e){try{StudyTimerStore.change(this,s.id,"pause");}catch(Exception ignored){}stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return START_NOT_STICKY;}}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public void onDestroy(){handler.removeCallbacks(limit);if(clockReceiverRegistered)unregisterReceiver(clockChanged);super.onDestroy();}
}
